var Arr=(input.trim()).split("\n");
while(true){
   var n=Arr.shift()-0;
   if(n==0)break;
   var arr=(Arr.shift()).split(" ").map(Number);
   var cnt=0;
   while(true){
      var flag=arr.every(function(v,i){return (i+1==v);});
