      var L=arr.length;
      arr=arr.map(function(v){return v-1;});
      arr=arr.filter(function(v){return (v!=0);});
      arr.push(L);
      cnt++;
      if(cnt==10000){cnt=-1;break;}
   }
   console.log(cnt);
